// Snapshot for the /robot page. Every value is written by the MQTT pipelines feeding the /ui dashboard.
msg.payload = {
    command: flow.get('pageCommand') || null,
    response: flow.get('lastResponse') || { state: 'UNKNOWN', detail: 'No MQTT response received yet' },
    distance: flow.get('pageDistance') || null,
    gas: flow.get('pageGas') || null,
    alert: flow.get('alertState') || null,
    vision: flow.get('pageVision') || null,
    camera: flow.get('pageCamera') || null,
    remote: flow.get('pageRemote') || null,
    serverTime: Date.now()
};
msg.headers = { 'Cache-Control': 'no-store' };
return msg;

// Single sink for the /robot page; inputs are the same messages the /ui dashboard uses.
switch (msg.topic) {
    case 'command':
        flow.set('pageCommand', msg.payload);
        break;
    case 'distance':
        flow.set('pageDistance', msg.payload);
        break;
    case 'gas':
        flow.set('pageGas', msg.payload);
        break;
    case 'camera':
        flow.set('pageCamera', msg.payload);
        break;
    case 'remote':
        flow.set('pageRemote', msg.payload);
        break;
    case 'equipo1/robot/vision/status': {
        let status = msg.payload;
        if (typeof status === 'string') {
            const raw = status.trim();
            try { status = JSON.parse(raw); } catch (err) { status = { state: raw }; }
        }
        if (status && typeof status === 'object') {
            flow.set('pageVision', { ...status, receivedAt: Date.now() });
        }
        break;
    }
}
return null;

let payload = msg.payload;
if (typeof payload === 'string') {
    try { payload = JSON.parse(payload); } catch (err) { node.warn('Ignored invalid MQTT response'); return null; }
}
if (!payload || typeof payload !== 'object' || Array.isArray(payload)) {
    node.warn('Ignored invalid MQTT response');
    return null;
}
payload.receivedAt = new Date().toISOString();
flow.set('lastResponse', payload);
return msg;

let payload = msg.payload;
if (typeof payload === 'string') {
    try { payload = JSON.parse(payload); } catch (err) { node.warn('Ignored invalid MQTT telemetry'); return null; }
}
if (!payload || typeof payload !== 'object' || Array.isArray(payload)) {
    node.warn('Ignored invalid MQTT telemetry');
    return null;
}
payload.receivedAt = new Date().toISOString();
flow.set('lastTelemetry', payload);
return msg;

let status = msg.payload;
if (typeof status === 'string') {
    const raw = status.trim();
    try { status = JSON.parse(raw); } catch (err) { status = { state: raw }; }
}
if (!status || typeof status !== 'object') {
    return [{ payload: 'Estado desconocido' }, null];
}
if (status.state !== 'online') {
    return [{ payload: 'Servidor de cámara desconectado' }, null];
}
const LABELS = { none: 'Original', canny: 'Canny', blackhat: 'Black-hat', sobel: 'Sobel', laplacian: 'Laplaciano' };
const camera = status.connected === false ? 'cámara sin señal' : 'cámara conectada';
const fps = Number.isFinite(Number(status.fps)) ? `${Number(status.fps).toFixed(0)} fps` : '— fps';
const filter = LABELS[status.filter] || 'Original';
const cost = typeof status.filterMs === 'number' ? ` (${status.filterMs.toFixed(0)} ms)` : '';
const text = { payload: `En línea · ${camera} · ${fps} · ${filter}${cost}` };
if (!status.filter || status.filter === context.get('filter')) return [text, null];
context.set('filter', status.filter);
return [text, { payload: status.filter }];

if (msg.topic === 'base' && typeof msg.payload === 'string' && msg.payload.trim()) {
    context.set('base', msg.payload.trim().replace(/\/+$/, ''));
} else if (msg.topic === 'view') {
    context.set('view', msg.payload === true ? 'filtered' : 'raw');
} else {
    return null;
}
const base = context.get('base');
if (!base) return null;
return { payload: { base, view: context.get('view') || 'raw' } };

// Shared by the /ui dropdown and POST /robot/vision/filter.
// Output 1 feeds the only mqtt out node in this flow, hard-wired to equipo1/robot/vision/filter.
const MODES = ['none', 'canny', 'blackhat', 'sobel', 'laplacian'];
const fromHttp = !!msg.res;
const body = msg.payload;
const requested = typeof body === 'string' ? body : (body && typeof body === 'object' ? body.filter : null);
const filter = String(requested || '').trim().toLowerCase();
if (!MODES.includes(filter)) {
    if (!fromHttp) { node.warn(`Ignored unknown filter: ${requested}`); return [null, null]; }
    msg.statusCode = 400;
    msg.payload = { ok: false, error: 'Invalid filter', allowed: MODES };
    return [null, msg];
}
const publish = { payload: filter, qos: 1, retain: true };
if (!fromHttp) return [publish, null];
msg.payload = { ok: true, filter };
return [publish, msg];

// equipo1/robot/command contract (firmware/remote_control_mqtt):
//   {"command":"DRIVE","left","right","x","y" (-255..255),"speed","seq"} at 10 Hz,
//   {"command":"STOP","seq"} and {"command":"PATROL","seq"} on button presses.
// Legacy commands FORWARD/BACKWARD/CW/CCW/STOP/RECTANGLE (optional "x"/"y" in -100..100,
// optional "motorASpeed"/"motorBSpeed") are still accepted.
// Output: one normalized state for both UIs; x/y are scaled to -100..100.
const LEGACY_MOVES = ['FORWARD', 'BACKWARD', 'CW', 'CCW'];
const COMMANDS = ['DRIVE', 'STOP', 'PATROL', 'RECTANGLE', ...LEGACY_MOVES];
// |left| or |right| below this counts as no motion.
const DEAD_BAND = 20;

// D-pad direction from the differential motor commands.
function deriveDirection(left, right) {
    const l = Math.abs(left) < DEAD_BAND ? 0 : left;
    const r = Math.abs(right) < DEAD_BAND ? 0 : right;
    if (l === 0 && r === 0) return 'IDLE';
    if (l > 0 && r > 0) return 'FORWARD';
    if (l < 0 && r < 0) return 'BACKWARD';
    return l > r ? 'CW' : 'CCW';
}

let payload = msg.payload;
if (typeof payload === 'string') {
    try { payload = JSON.parse(payload); } catch (err) { node.warn('Ignored invalid equipo1/robot/command'); return null; }
}
if (!payload || typeof payload !== 'object' || Array.isArray(payload)) {
    node.warn('Ignored invalid equipo1/robot/command');
    return null;
}
const command = String(payload.command || '').trim().toUpperCase();
if (!COMMANDS.includes(command)) {
    node.warn(`Ignored unknown command: ${command}`);
    return null;
}
const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));
const num = (v) => (typeof v === 'number' && Number.isFinite(v) ? v : null);

// STOP, PATROL and RECTANGLE are one-shot messages; keep showing them while the
// following DRIVE messages are idle, until real motion or another command arrives.
let mode = context.get('mode') || null;
let direction;
let left = null;
let right = null;
switch (command) {
    case 'DRIVE':
        left = clamp(Math.round(num(payload.left) ?? 0), -255, 255);
        right = clamp(Math.round(num(payload.right) ?? 0), -255, 255);
        direction = deriveDirection(left, right);
        if (direction !== 'IDLE') mode = null;
        break;
    case 'STOP':
    case 'PATROL':
    case 'RECTANGLE':
        mode = command;
        direction = 'IDLE';
        break;
    default:
        mode = null;
        direction = command;
}
context.set('mode', mode);
if (mode === 'STOP') direction = 'STOP';

const axisScale = command === 'DRIVE' ? 100 / 255 : 1;
const axis = (v) => (v === null ? 0 : clamp(Math.round(v * axisScale), -100, 100));
const speed = num(payload.speed);
const axisX = num(payload.x);
const axisY = num(payload.y);
msg.payload = {
    command,
    direction,
    routine: mode === 'PATROL' || mode === 'RECTANGLE' ? mode : null,
    hasMotors: left !== null,
    left,
    right,
    speed: speed === null ? null : clamp(Math.round(speed), 0, 255),
    motorASpeed: num(payload.motorASpeed),
    motorBSpeed: num(payload.motorBSpeed),
    hasJoystick: axisX !== null && axisY !== null,
    x: axis(axisX),
    y: axis(axisY),
    seq: num(payload.seq),
    receivedAt: Date.now()
};
msg.topic = 'command';
return msg;

// equipo1/robot/camera (firmware/remote_control_mqtt): {"pan","tilt"} rates in -255..255 at 10 Hz
// while the camera joystick is off-center plus one final zero, or {"command":"CENTER"}.
let payload = msg.payload;
if (typeof payload === 'string') {
    try { payload = JSON.parse(payload); } catch (err) { node.warn('Ignored invalid equipo1/robot/camera'); return null; }
}
if (!payload || typeof payload !== 'object' || Array.isArray(payload)) {
    node.warn('Ignored invalid equipo1/robot/camera');
    return null;
}
const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));
const num = (v) => (typeof v === 'number' && Number.isFinite(v) ? v : null);
const now = Date.now();
const state = Object.assign({ pan: 0, tilt: 0, movedAt: null, centerAt: null }, context.get('state'));

if (String(payload.command || '').trim().toUpperCase() === 'CENTER') {
    state.centerAt = now;
} else if (num(payload.pan) !== null || num(payload.tilt) !== null) {
    state.pan = clamp(Math.round(num(payload.pan) ?? 0), -255, 255);
    state.tilt = clamp(Math.round(num(payload.tilt) ?? 0), -255, 255);
    state.movedAt = now;
} else {
    node.warn('Ignored invalid equipo1/robot/camera');
    return null;
}
state.receivedAt = now;
context.set('state', state);
msg.topic = 'camera';
msg.payload = { ...state };
return msg;

// equipo1/robot/remote/status (retained, firmware/remote_control_mqtt), every 2 s and on change:
//   {"state":"online","speed","stopLatched","battery":volts|null,"rssi","uptimeMs"}
// Last will: {"state":"offline"}.
let payload = msg.payload;
if (typeof payload === 'string') {
    try { payload = JSON.parse(payload); } catch (err) { node.warn('Ignored invalid equipo1/robot/remote/status'); return null; }
}
if (!payload || typeof payload !== 'object' || Array.isArray(payload)) {
    node.warn('Ignored invalid equipo1/robot/remote/status');
    return null;
}
const state = String(payload.state || '').trim().toLowerCase();
if (state !== 'online' && state !== 'offline') {
    node.warn(`Ignored unknown remote state: ${state}`);
    return null;
}
const num = (v) => (typeof v === 'number' && Number.isFinite(v) ? v : null);
msg.topic = 'remote';
msg.payload = {
    state,
    speed: num(payload.speed),
    stopLatched: payload.stopLatched === true,
    battery: num(payload.battery),
    rssi: num(payload.rssi),
    uptimeMs: num(payload.uptimeMs),
    receivedAt: Date.now()
};
return msg;

// Feeds the /ui templates: 1) direction/speed, 2) robot state, 3) remote link + camera joystick.
// equipo1/robot/command arrives at 10 Hz, so updates are throttled to one every MIN_INTERVAL_MS (<= 5 Hz):
// intermediate states are dropped and the latest one is always delivered (trailing flush).
// One-shot events (STOP, PATROL, CENTER) survive the throttle because they are sticky state.
const MIN_INTERVAL_MS = 200;
const dirty = context.get('dirty') || { cmd: false, res: false, link: false };
switch (msg.topic) {
    case 'tick':
        dirty.cmd = dirty.res = dirty.link = true;
        break;
    case 'command':
        context.set('command', msg.payload);
        dirty.cmd = true;
        break;
    case 'equipo1/robot/response':
        context.set('response', msg.payload);
        dirty.res = true;
        break;
    case 'camera':
        context.set('camera', msg.payload);
        dirty.link = true;
        break;
    case 'remote':
        context.set('remote', msg.payload);
        dirty.link = true;
        break;
    default:
        return null;
}
context.set('dirty', dirty);

function flush() {
    const d = context.get('dirty') || {};
    const now = Date.now();
    context.set('dirty', { cmd: false, res: false, link: false });
    context.set('flushScheduled', false);
    context.set('lastFlushAt', now);
    node.send([
        d.cmd ? { payload: { cmd: context.get('command') || null, now } } : null,
        d.res ? { payload: { res: context.get('response') || null, now } } : null,
        d.link ? { payload: { remote: context.get('remote') || null, camera: context.get('camera') || null, now } } : null
    ]);
}

const wait = MIN_INTERVAL_MS - (Date.now() - (context.get('lastFlushAt') || 0));
if (wait <= 0) {
    flush();
} else if (!context.get('flushScheduled')) {
    context.set('flushScheduled', true);
    setTimeout(flush, wait);
}
return null;

// equipo1/robot/telemetry carries one sensor per message, identified by payload.sensor.
switch (msg.payload && msg.payload.sensor) {
    case 'ultrasonic_distance': return [msg, null];
    case 'gas': return [null, msg];
    default: return [null, null];
}

const p = msg.payload;
const value = Number(p.value);
const valid = p.valid === true && typeof p.value === 'number' && Number.isFinite(value);
const alert = { topic: 'distance', payload: { valid, value: valid ? value : null, at: Date.now() } };
if (!valid) {
    // Gauge keeps its last value; the text and the alert banner carry the invalid state.
    return [null, { payload: 'Fuera de rango' }, alert];
}
return [{ payload: Math.round(value) }, { payload: `${value.toFixed(1)} cm` }, alert];

// Planned sensor: {"sensor":"gas","unit":"ppm","valid":bool,"value":number|null,...}
const p = msg.payload;
const value = Number(p.value);
const valid = p.valid !== false && typeof p.value === 'number' && Number.isFinite(value);
const unit = typeof p.unit === 'string' && p.unit ? p.unit : 'ppm';
const alert = { topic: 'gas', payload: { valid, value: valid ? value : null, unit, at: Date.now() } };
if (!valid) {
    return [null, { payload: 'Lectura inválida' }, alert];
}
return [{ payload: Math.round(value) }, { payload: `${value.toFixed(0)} ${unit}` }, alert];

const OBSTACLE_CM = 30;
// Placeholder until the gas sensor is chosen and calibrated (same unit the sensor publishes).
const GAS_ALERT_PPM = 400;
// Telemetry older than this is treated as missing (the firmware publishes several times per second).
const STALE_MS = 5000;

if (msg.topic === 'distance' || msg.topic === 'gas') {
    context.set(msg.topic, msg.payload);
}
const now = Date.now();
const distance = context.get('distance');
const gas = context.get('gas');
const fresh = (reading) => reading && now - reading.at < STALE_MS;

const alerts = [];
if (fresh(distance) && distance.valid && distance.value < OBSTACLE_CM) {
    alerts.push(`OBSTÁCULO a ${distance.value.toFixed(0)} cm`);
}
if (fresh(gas) && gas.valid && gas.value >= GAS_ALERT_PPM) {
    alerts.push(`GAS ${gas.value.toFixed(0)} ${gas.unit}`);
}

let banner;
if (alerts.length) {
    banner = { level: 'danger', text: alerts.join(' · ') };
} else if (!fresh(distance)) {
    banner = { level: 'unknown', text: 'SIN DATOS DE DISTANCIA' };
} else {
    banner = { level: 'safe', text: 'SEGURO' };
}
// Shared with the /robot page through GET /robot/status.
flow.set('alertState', { banner, thresholds: { obstacleCm: OBSTACLE_CM, gasAlertPpm: GAS_ALERT_PPM } });
const key = banner.level + banner.text;
if (key === context.get('lastBanner')) {
    return null;
}
context.set('lastBanner', key);
return { payload: banner };
